[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    /* ========== DESIGN TOKENS (OKLCH) ========== */
    :root {
      --green-primary: oklch(44% 0.12 155);
      --green-dark: oklch(35% 0.1 155);
      --green-light: oklch(55% 0.12 155);
      --green-pale: oklch(92% 0.04 155);
      --orange-accent: oklch(78% 0.14 55);
      --orange-hover: oklch(72% 0.15 55);
      --terracotta: oklch(65% 0.14 30);
      --yellow-pop: oklch(87% 0.15 90);
      --cream: oklch(99% 0.01 95);
      --cream-warm: oklch(97% 0.015 80);
      --white: oklch(100% 0 0);
      --text-primary: oklch(22% 0.03 155);
      --text-secondary: oklch(45% 0.03 155);
      --text-muted: oklch(55% 0.02 155);
      --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.06), 0 1px 2px oklch(0% 0 0 / 0.04);
      --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.07), 0 2px 4px oklch(0% 0 0 / 0.04);
      --shadow-lg: 0 10px 30px oklch(0% 0 0 / 0.08), 0 4px 8px oklch(0% 0 0 / 0.04);
      --shadow-xl: 0 20px 50px oklch(0% 0 0 / 0.1), 0 8px 16px oklch(0% 0 0 / 0.05);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
      --font-heading: 'Nunito', sans-serif;
      --font-body: 'Inter', sans-serif;
    }

    /* ========== RESET & BASE ========== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

    body {
      font-family: var(--font-body);
      background: var(--cream);
      color: var(--text-primary);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); line-height: 1.2; }

    a { text-decoration: none; color: inherit; }

    img { max-width: 100%; display: block; }

    button { cursor: pointer; border: none; background: none; font-family: inherit; }

    input { font-family: inherit; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ========== HEADER ========== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: oklch(100% 0 0 / 0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid oklch(0% 0 0 / 0.06);
      transition: box-shadow 0.3s ease;
    }

    .header.scrolled {
      box-shadow: var(--shadow-md);
    }

    .header .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: var(--font-heading);
      font-weight: 900;
      font-size: 1.5rem;
      color: var(--green-primary);
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--green-primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 1.1rem;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      font-weight: 600;
      font-size: 0.95rem;
      color: var(--text-secondary);
      transition: color 0.2s ease;
      position: relative;
    }

    .nav-links a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--orange-accent);
      border-radius: 1px;
      transition: width 0.3s ease;
    }

    .nav-links a:hover { color: var(--green-primary); }
    .nav-links a:hover::after { width: 100%; }

    .nav-cta {
      background: var(--green-primary);
      color: var(--white) !important;
      padding: 10px 22px;
      border-radius: var(--radius-full);
      font-weight: 700;
      font-size: 0.9rem;
      transition: background 0.2s ease, transform 0.15s ease;
    }

    .nav-cta::after { display: none !important; }
    .nav-cta:hover { background: var(--green-dark); transform: translateY(-1px); }

    .mobile-toggle {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 4px;
    }

    .mobile-toggle span {
      width: 24px;
      height: 2.5px;
      background: var(--green-primary);
      border-radius: 2px;
      transition: transform 0.3s ease;
    }

    /* ========== HERO ========== */
    .hero {
      position: relative;
      padding: 100px 0 80px;
      background: linear-gradient(165deg, var(--cream) 0%, var(--green-pale) 50%, var(--cream) 100%);
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -80px;
      right: -120px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, oklch(87% 0.15 90 / 0.25), transparent 70%);
      border-radius: 50%;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px;
      left: -80px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, oklch(55% 0.12 155 / 0.08), transparent 70%);
      border-radius: 50%;
    }

    .hero .container {
      display: flex;
      align-items: center;
      gap: 60px;
      position: relative;
      z-index: 1;
    }

    .hero-content { flex: 1; max-width: 560px; }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: oklch(87% 0.15 90 / 0.5);
      color: var(--terracotta);
      padding: 6px 16px;
      border-radius: var(--radius-full);
      font-size: 0.85rem;
      font-weight: 600;
      margin-bottom: 20px;
    }

    .hero h1 {
      font-size: clamp(2.4rem, 5vw, 3.6rem);
      font-weight: 900;
      color: var(--green-primary);
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero p {
      font-size: 1.15rem;
      color: var(--text-secondary);
      margin-bottom: 32px;
      line-height: 1.7;
    }

    .hero-buttons {
      display: flex;
      gap: 14px;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: var(--radius-full);
      font-weight: 700;
      font-size: 1rem;
      transition: all 0.2s ease;
    }

    .btn-primary {
      background: var(--green-primary);
      color: var(--white);
      box-shadow: 0 4px 16px oklch(44% 0.12 155 / 0.3);
    }

    .btn-primary:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 24px oklch(44% 0.12 155 / 0.35);
    }

    .btn-secondary {
      background: var(--white);
      color: var(--green-primary);
      border: 2px solid oklch(44% 0.12 155 / 0.2);
    }

    .btn-secondary:hover {
      background: var(--green-pale);
      border-color: var(--green-primary);
      transform: translateY(-2px);
    }

    .hero-visual {
      flex: 1;
      display: flex;
      justify-content: center;
      position: relative;
    }

    .hero-image-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
      transform: rotate(2deg);
    }

    .hero-img-card {
      width: 180px;
      height: 180px;
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-lg);
    }

    .hero-img-card:nth-child(2) { transform: translateY(24px); }
    .hero-img-card:nth-child(3) { transform: translateY(-12px); }

    .hero-img-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .hero-img-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.5rem;
    }

    .hero-img-placeholder.prod-1 { background: oklch(78% 0.14 55 / 0.25); }
    .hero-img-placeholder.prod-2 { background: oklch(55% 0.12 155 / 0.15); }
    .hero-img-placeholder.prod-3 { background: oklch(87% 0.15 90 / 0.35); }
    .hero-img-placeholder.prod-4 { background: oklch(65% 0.14 30 / 0.2); }

    /* ========== SECTION SHARED ========== */
    .section { padding: 80px 0; }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-label {
      display: inline-block;
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--orange-accent);
      margin-bottom: 8px;
    }

    .section-title {
      font-size: clamp(1.8rem, 3.5vw, 2.5rem);
      font-weight: 800;
      color: var(--green-primary);
      margin-bottom: 12px;
    }

    .section-subtitle {
      font-size: 1.05rem;
      color: var(--text-secondary);
      max-width: 560px;
      margin: 0 auto;
    }

    /* ========== FEATURED PRODUCTS CAROUSEL ========== */
    .featured-products {
      background: var(--white);
      position: relative;
    }

    .carousel-wrapper {
      position: relative;
      overflow: hidden;
      padding: 8px 0;
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      transition: transform 0.45s cubic-bezier(0.25, 0.8, 0.25, 1);
      will-change: transform;
    }

    .product-card {
      flex: 0 0 260px;
      background: var(--cream);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: transform 0.25s ease, box-shadow 0.25s ease;
    }

    .product-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .product-card-img {
      width: 100%;
      height: 200px;
      position: relative;
      overflow: hidden;
    }

    .product-card-img .placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }

    .product-card-body {
      padding: 18px 20px 20px;
    }

    .product-card-name {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 1.05rem;
      color: var(--text-primary);
      margin-bottom: 6px;
    }

    .product-card-desc {
      font-size: 0.85rem;
      color: var(--text-muted);
      line-height: 1.5;
      margin-bottom: 12px;
    }

    .product-card-price {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 1.15rem;
      color: var(--green-primary);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--white);
      box-shadow: var(--shadow-md);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10;
      transition: all 0.2s ease;
      border: 1px solid oklch(0% 0 0 / 0.06);
    }

    .carousel-btn:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-50%) scale(1.05);
    }

    .carousel-btn:active { transform: translateY(-50%) scale(0.96); }

    .carousel-btn.prev { left: -8px; }
    .carousel-btn.next { right: -8px; }

    .carousel-btn svg {
      width: 20px;
      height: 20px;
      stroke: var(--green-primary);
      stroke-width: 2.5;
      fill: none;
    }

    .carousel-dots {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-top: 28px;
    }

    .carousel-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: oklch(0% 0 0 / 0.1);
      transition: all 0.3s ease;
      cursor: pointer;
    }

    .carousel-dot.active {
      background: var(--green-primary);
      width: 28px;
      border-radius: 5px;
    }

    /* Product placeholder colors */
    .ph-granola { background: oklch(80% 0.08 75); }
    .ph-seasoning { background: oklch(85% 0.06 55); }
    .ph-chocolate { background: oklch(35% 0.06 55); }
    .ph-gnocchi { background: oklch(88% 0.06 80); }
    .ph-chicken { background: oklch(82% 0.1 55); }
    .ph-cheese { background: oklch(87% 0.12 85); }
    .ph-lemonade { background: oklch(85% 0.14 90); }
    .ph-almonds { background: oklch(70% 0.06 50); }

    /* ========== SEASONAL PICKS ========== */
    .seasonal-picks {
      background: linear-gradient(180deg, var(--cream) 0%, var(--cream-warm) 100%);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
      gap: 24px;
    }

    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: transform 0.25s ease, box-shadow 0.25s ease;
    }

    .seasonal-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .seasonal-card-img {
      height: 180px;
      overflow: hidden;
    }

    .seasonal-card-img .placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }

    .ph-watermelon { background: oklch(78% 0.14 145 / 0.3); }
    .ph-peach { background: oklch(82% 0.12 55 / 0.3); }
    .ph-coconut { background: oklch(88% 0.06 80 / 0.3); }
    .ph-mango { background: oklch(87% 0.15 90 / 0.35); }

    .seasonal-card-body {
      padding: 20px;
    }

    .seasonal-card-name {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 1.05rem;
      margin-bottom: 6px;
    }

    .seasonal-card-desc {
      font-size: 0.88rem;
      color: var(--text-muted);
      line-height: 1.5;
      margin-bottom: 12px;
    }

    .seasonal-card-price {
      font-family: var(--font-heading);
      font-weight: 800;
      color: var(--green-primary);
      font-size: 1.05rem;
    }

    .seasonal-limited-badge {
      display: inline-block;
      background: oklch(87% 0.15 90 / 0.5);
      color: var(--terracotta);
      font-size: 0.75rem;
      font-weight: 700;
      padding: 3px 10px;
      border-radius: var(--radius-full);
      margin-left: 10px;
      vertical-align: middle;
    }

    /* ========== CATEGORIES ========== */
    .categories {
      background: var(--white);
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 20px;
    }

    .category-card {
      position: relative;
      height: 220px;
      border-radius: var(--radius-lg);
      overflow: hidden;
      cursor: pointer;
      box-shadow: var(--shadow-sm);
    }

    .category-card-bg {
      position: absolute;
      inset: 0;
      transition: transform 0.4s ease;
    }

    .category-card:hover .category-card-bg {
      transform: scale(1.08);
    }

    .category-card-overlay {
      position: absolute;
      inset: 0;
      background: oklch(0% 0 0 / 0);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      text-align: center;
      padding: 20px;
      transition: all 0.35s ease;
    }

    .category-card:hover .category-card-overlay {
      background: oklch(35% 0.1 155 / 0.65);
    }

    .category-emoji {
      font-size: 2.8rem;
      margin-bottom: 10px;
      transition: transform 0.35s ease;
    }

    .category-card:hover .category-emoji {
      transform: scale(1.15);
    }

    .category-name {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 1.1rem;
      color: var(--white);
      opacity: 0;
      transform: translateY(10px);
      transition: all 0.35s ease;
    }

    .category-card:hover .category-name {
      opacity: 1;
      transform: translateY(0);
    }

    .category-desc {
      font-size: 0.82rem;
      color: oklch(95% 0.02 155);
      margin-top: 6px;
      opacity: 0;
      transform: translateY(8px);
      transition: all 0.35s ease 0.05s;
    }

    .category-card:hover .category-desc {
      opacity: 1;
      transform: translateY(0);
    }

    .cat-snacks { background: linear-gradient(135deg, oklch(82% 0.1 55), oklch(78% 0.14 55)); }
    .cat-produce { background: linear-gradient(135deg, oklch(70% 0.14 145), oklch(65% 0.12 155)); }
    .cat-frozen { background: linear-gradient(135deg, oklch(85% 0.06 220), oklch(80% 0.08 230)); }
    .cat-beverages { background: linear-gradient(135deg, oklch(87% 0.12 90), oklch(82% 0.1 80)); }
    .cat-dairy { background: linear-gradient(135deg, oklch(90% 0.08 80), oklch(85% 0.06 75)); }

    /* ========== BRAND HIGHLIGHTS ========== */
    .brand-highlights {
      background: var(--green-primary);
      padding: 60px 0;
      position: relative;
      overflow: hidden;
    }

    .brand-highlights::before {
      content: '';
      position: absolute;
      top: -60px;
      right: -60px;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, oklch(55% 0.12 155 / 0.3), transparent 70%);
      border-radius: 50%;
    }

    .brand-highlights::after {
      content: '';
      position: absolute;
      bottom: -80px;
      left: -40px;
      width: 250px;
      height: 250px;
      background: radial-gradient(circle, oklch(78% 0.14 55 / 0.15), transparent 70%);
      border-radius: 50%;
    }

    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      position: relative;
      z-index: 1;
    }

    .highlight-item {
      text-align: center;
      padding: 20px;
    }

    .highlight-number {
      font-family: var(--font-heading);
      font-weight: 900;
      font-size: clamp(2rem, 4vw, 2.8rem);
      color: var(--yellow-pop);
      margin-bottom: 6px;
      line-height: 1;
    }

    .highlight-label {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 1rem;
      color: var(--white);
      margin-bottom: 4px;
    }

    .highlight-desc {
      font-size: 0.82rem;
      color: oklch(90% 0.03 155);
      line-height: 1.4;
    }

    /* ========== STORE LOCATOR ========== */
    .store-locator {
      background: linear-gradient(180deg, var(--cream-warm) 0%, var(--cream) 100%);
    }

    .locator-card {
      max-width: 700px;
      margin: 0 auto;
      background: var(--white);
      border-radius: var(--radius-xl);
      padding: 40px;
      box-shadow: var(--shadow-lg);
      text-align: center;
    }

    .locator-icon {
      width: 56px;
      height: 56px;
      background: var(--green-pale);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
      font-size: 1.5rem;
    }

    .locator-card .section-title {
      margin-bottom: 8px;
    }

    .locator-card .section-subtitle {
      margin-bottom: 28px;
    }

    .locator-form {
      display: flex;
      gap: 12px;
      max-width: 420px;
      margin: 0 auto;
    }

    .locator-input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid oklch(0% 0 0 / 0.08);
      border-radius: var(--radius-full);
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s ease;
      background: var(--cream);
    }

    .locator-input:focus {
      border-color: var(--green-primary);
    }

    .locator-input::placeholder {
      color: var(--text-muted);
    }

    .locator-btn {
      padding: 14px 28px;
      background: var(--orange-accent);
      color: var(--white);
      border-radius: var(--radius-full);
      font-weight: 700;
      font-size: 0.95rem;
      transition: all 0.2s ease;
      white-space: nowrap;
    }

    .locator-btn:hover {
      background: var(--orange-hover);
      transform: translateY(-1px);
    }

    .store-results {
      margin-top: 28px;
      text-align: left;
      display: none;
    }

    .store-results.visible { display: block; }

    .store-result {
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 16px;
      border-radius: var(--radius-md);
      background: var(--cream);
      margin-bottom: 10px;
      transition: background 0.2s ease;
    }

    .store-result:hover { background: var(--green-pale); }

    .store-result-icon {
      width: 42px;
      height: 42px;
      background: var(--green-primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 1.1rem;
      flex-shrink: 0;
    }

    .store-result-info { flex: 1; }

    .store-result-name {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 0.95rem;
      margin-bottom: 2px;
